  // ---------- equipment builders
  function roundedPath(input, r = 0.03) {
    const pts = input.filter((p, i) => i === 0 || p.distanceTo(input[i - 1]) > 1e-5);
    const path = new THREE.CurvePath();
    let prev = pts[0].clone();
    for (let i = 1; i < pts.length - 1; i++) {
      const p = pts[i];
      const a = p.clone().sub(pts[i - 1]).normalize(), b = pts[i + 1].clone().sub(p).normalize();
      const dp = Math.min(r, p.distanceTo(pts[i - 1]) / 2), dn = Math.min(r, p.distanceTo(pts[i + 1]) / 2);
      const s = p.clone().addScaledVector(a, -dp), e = p.clone().addScaledVector(b, dn);
      if (prev.distanceTo(s) > 1e-5) path.add(new THREE.LineCurve3(prev.clone(), s));
      path.add(new THREE.QuadraticBezierCurve3(s, p.clone(), e));
      prev = e;
    }
    path.add(new THREE.LineCurve3(prev.clone(), pts[pts.length - 1].clone()));
    return path;
  }
  const samplePath = (path, step = 0.012) => path.getSpacedPoints(Math.max(4, Math.round(path.getLength() / step)));

  function makePipe(pts, { radius = 0.014, corner = 0.03, parent = null, mat = M.sheath } = {}) {
    const path = roundedPath(pts, corner);
    const samples = samplePath(path);
    let mesh = null;
    if (parent) {
      mesh = new THREE.Mesh(new THREE.TubeGeometry(path, Math.max(8, Math.round(path.getLength() / 0.02)), radius, 10, false), mat);
      mesh.renderOrder = 2; parent.add(mesh);
    }
    return { path, samples, mesh, radius };
  }

  function makeCoil({ H, D, W, rows = 2, cols, dropLast = false, zFlip = false, finPitch = 0.009, tubeR = 0.0072, pos, rot = 0, parent }) {
    const g = new THREE.Group(); g.position.copy(pos); g.rotation.z = rot; parent.add(g);
    const nFins = Math.round(H / finPitch), m4 = new THREE.Matrix4();
    const fins = new THREE.InstancedMesh(new THREE.BoxGeometry(D, 0.0013, W), M.fin, nFins);
    for (let i = 0; i < nFins; i++) { m4.makeTranslation(0, -H / 2 + (i + 0.5) * H / nFins, 0); fins.setMatrixAt(i, m4); }
    fins.receiveShadow = true; g.add(fins);
    const pitchC = (W - 0.06 - (rows > 1 ? 0.02 : 0)) / (cols - 1);
    const dir = zFlip ? -1 : 1, z0 = -dir * (W / 2 - 0.03);
    const tubes = [];
    for (let c = 0; c < cols; c++) for (let r = 0; r < rows; r++) tubes.push({ x: (r - (rows - 1) / 2) * (D / rows), z: z0 + dir * (c * pitchC + (r % 2) * pitchC / 2) });
    if (dropLast) tubes.pop();
    const n = tubes.length;
    const tubeMesh = new THREE.InstancedMesh(new THREE.CylinderGeometry(tubeR, tubeR, H + 0.003, 10, 1), M.copperTint, n);
    const base = C(0xd2793f);
    tubes.forEach((t, i) => { m4.makeTranslation(t.x, 0, t.z); tubeMesh.setMatrixAt(i, m4); tubeMesh.setColorAt(i, base); });
    tubeMesh.castShadow = true; g.add(tubeMesh);
    const bendGeos = [], local = [];
    for (let i = 0; i < n; i++) {
      const t = tubes[i], top = i % 2 === 0;
      local.push(V(t.x, top ? H / 2 : -H / 2, t.z), V(t.x, top ? -H / 2 : H / 2, t.z));
      if (i === n - 1) break;
      const yEnd = top ? -H / 2 : H / 2, sign = yEnd > 0 ? 1 : -1, B = tubes[i + 1];
      const A3 = V(t.x, yEnd, t.z), B3 = V(B.x, yEnd, B.z), v = B3.clone().sub(A3), d = v.length(), rb = d / 2, vh = v.clone().normalize(), mid = A3.clone().add(B3).multiplyScalar(0.5);
      const pts = [];
      for (let k = 0; k <= 12; k++) {
        const th = Math.PI * k / 12;
        pts.push(mid.clone().addScaledVector(vh, -rb * Math.cos(th)).add(V(0, sign * rb * Math.sin(th), 0)));
      }
      for (let k = 1; k < 12; k++) local.push(pts[k].clone());
      bendGeos.push(new THREE.TubeGeometry(new THREE.CatmullRomCurve3(pts), 12, tubeR, 8, false));
    }
    const bends = new THREE.Mesh(mergeGeometries(bendGeos), M.copper); bends.castShadow = true; g.add(bends);
    g.updateMatrix();
    const path = local.map(p => p.applyMatrix4(g.matrix));
    const dewGeo = new THREE.SphereGeometry(1, 8, 6);
    const dew = new THREE.InstancedMesh(dewGeo, M.dew, 90); dew.frustumCulled = false; g.add(dew);
    const maxZ = Math.max(...tubes.map(t => t.z)), near = tubes.filter(t => t.z > maxZ - 0.14);
    const dewData = Array.from({ length: 90 }, (_, i) => {
      const t = (i < 55 ? near : tubes)[(rand() * (i < 55 ? near : tubes).length) | 0], a = rand() * 6.283;
      return { p: V(t.x + Math.cos(a) * (tubeR + 0.002), (rand() - 0.5) * H * 0.96, t.z + Math.sin(a) * (tubeR + 0.002)), r: 0.0032 + rand() * 0.004, ph: rand() * 0.6 };
    });
    const coil = {
      group: g, path, tubes, n, H, D, W, center: pos.clone(), dewLevel: -1,
      setTint(cA, cB) {
        const c = new THREE.Color();
        tubes.forEach((_, i) => { c.copy(base).lerp(cA.clone().lerp(cB, i / (n - 1)), 0.6); tubeMesh.setColorAt(i, c); });
        tubeMesh.instanceColor.needsUpdate = true;
      },
      setDew(level, time) {
        if (level === this.dewLevel && level === 0) return;
        this.dewLevel = level;
        const q = new THREE.Quaternion();
        dewData.forEach((d, i) => {
          const s = d.r * smooth(d.ph, d.ph + 0.4, level) * (1 + 0.1 * Math.sin(time * 1.6 + d.ph * 11));
          m4.compose(d.p, q, V(s, s * 1.15, s)); dew.setMatrixAt(i, m4);
        });
        dew.instanceMatrix.needsUpdate = true;
      },
    };
    coil.setDew(0, 0);
    return coil;
  }
  M.dew = phys({ color: 0xe4f6ff, roughness: 0.05, metalness: 0, transparent: true, opacity: 0.85, clearcoat: 1 });

  function makeCrossFan({ R, L, pos, parent, blades = 24 }) {
    const g = new THREE.Group(); g.position.copy(pos); parent.add(g);
    const spin = new THREE.Group(); g.add(spin);
    const bl = new THREE.InstancedMesh(new THREE.BoxGeometry(0.004, R * 0.34, L), M.blade, blades);
    const m4 = new THREE.Matrix4(), q = new THREE.Quaternion(), p = V(), s = V(1, 1, 1);
    for (let i = 0; i < blades; i++) {
      const a = (i / blades) * Math.PI * 2;
      p.set(Math.cos(a) * R * 0.82, Math.sin(a) * R * 0.82, 0);
      q.setFromEuler(new THREE.Euler(0, 0, a - Math.PI / 2 + 0.65)); m4.compose(p, q, s); bl.setMatrixAt(i, m4);
    }
    bl.castShadow = true; spin.add(bl);
    const ringGeo = new THREE.RingGeometry(R * 0.55, R, 40);
    [-L / 2, 0].forEach(z => { const r = new THREE.Mesh(ringGeo, M.blade); r.position.z = z; spin.add(r); });
    spin.add(cyl(0.008, 0.008, L + 0.02, M.steel, { axis: 'z', seg: 10 }));
    return { group: g, spin, R, L };
  }

  function makeAxialFan({ R, pos, parent, blades = 5 }) {
    const g = new THREE.Group(); g.position.copy(pos); parent.add(g);
    const spin = new THREE.Group(); g.add(spin);
    const sh = new THREE.Shape();
    sh.moveTo(0.04, -0.018); sh.bezierCurveTo(R * 0.4, -0.05, R * 0.8, -0.075, R, -0.05);
