// ---------- equipment builders
function roundedPath(input, r = 0.03) {
  const pts = input.filter((p, i) => i === 0 || p.distanceTo(input[i - 1]) > 1e-5);
  const path = new THREE.CurvePath();
  let prev = pts[0].clone();
  for (let i = 1; i < pts.length - 1; i++) {
    const p = pts[i];
    const a = p.clone().sub(pts[i - 1]).normalize(), b = pts[i + 1].clone().sub(p).normalize();
    const dp = Math.min(r, p.distanceTo(pts[i - 1]) / 2), dn = Math.min(r, p.distanceTo(pts[i + 1]) / 2);
    const s = p.clone().addScaledVector(a, -dp), e = p.clone().addScaledVector(b, dn);
    if (prev.distanceTo(s) > 1e-5) path.add(new THREE.LineCurve3(prev.clone(), s));
    path.add(new THREE.QuadraticBezierCurve3(s, p.clone(), e));
    prev = e;
  }
  path.add(new THREE.LineCurve3(prev.clone(), pts[pts.length - 1].clone()));
  return path;
}
const samplePath = (path, step = 0.012) => path.getSpacedPoints(Math.max(4, Math.round(path.getLength() / step)));

function makePipe(pts, { radius = 0.014, corner = 0.03, parent = null, mat = M.sheath } = {}) {
  const path = roundedPath(pts, corner);
  const samples = samplePath(path);
  let mesh = null;
  if (parent) {
    mesh = new THREE.Mesh(new THREE.TubeGeometry(path, Math.max(8, Math.round(path.getLength() / 0.02)), radius, 10, false), mat);
    mesh.renderOrder = 2; parent.add(mesh);
  }
  return { path, samples, mesh, radius };
}

