  if (dropLast) tubes.pop();
  const n = tubes.length;
  const tubeMesh = new THREE.InstancedMesh(new THREE.CylinderGeometry(tubeR, tubeR, H + 0.003, 10, 1), M.copperTint, n);
  const base = C(0xd2793f);
  tubes.forEach((t, i) => { m4.makeTranslation(t.x, 0, t.z); tubeMesh.setMatrixAt(i, m4); tubeMesh.setColorAt(i, base); });
  tubeMesh.castShadow = true; g.add(tubeMesh);
  const bendGeos = [], local = [];
  for (let i = 0; i < n; i++) {
    const t = tubes[i], top = i % 2 === 0;
