    return { p: V(t.x + Math.cos(a) * (tubeR + 0.002), (rand() - 0.5) * H * 0.96, t.z + Math.sin(a) * (tubeR + 0.002)), r: 0.0032 + rand() * 0.004, ph: rand() * 0.6 };
  });
