function makeCrossFan({ R, L, pos, parent, blades = 24 }) {
  const g = new THREE.Group(); g.position.copy(pos); parent.add(g);
  const spin = new THREE.Group(); g.add(spin);
  const bl = new THREE.InstancedMesh(new THREE.BoxGeometry(0.004, R * 0.34, L), M.blade, blades);
  const m4 = new THREE.Matrix4(), q = new THREE.Quaternion(), p = V(), s = V(1, 1, 1);
  for (let i = 0; i < blades; i++) {
    const a = (i / blades) * Math.PI * 2;
    p.set(Math.cos(a) * R * 0.82, Math.sin(a) * R * 0.82, 0);
    q.setFromEuler(new THREE.Euler(0, 0, a - Math.PI / 2 + 0.65)); m4.compose(p, q, s); bl.setMatrixAt(i, m4);
  }
  bl.castShadow = true; spin.add(bl);
  const ringGeo = new THREE.RingGeometry(R * 0.55, R, 40);
  [-L / 2, 0].forEach(z => { const r = new THREE.Mesh(ringGeo, M.blade); r.position.z = z; spin.add(r); });
  spin.add(cyl(0.008, 0.008, L + 0.02, M.steel, { axis: 'z', seg: 10 }));
  return { group: g, spin, R, L };
}

function makeAxialFan({ R, pos, parent, blades = 5 }) {
  const g = new THREE.Group(); g.position.copy(pos); parent.add(g);
  const spin = new THREE.Group(); g.add(spin);
  const sh = new THREE.Shape();
  sh.moveTo(0.04, -0.018); sh.bezierCurveTo(R * 0.4, -0.05, R * 0.8, -0.075, R, -0.05);
  sh.bezierCurveTo(R * 1.02, 0, R * 0.98, 0.03, R * 0.7, 0.05); sh.bezierCurveTo(R * 0.4, 0.06, 0.15, 0.045, 0.04, 0.02); sh.closePath();
  const bg = new THREE.ExtrudeGeometry(sh, { depth: 0.004, bevelEnabled: false }); bg.translate(0, 0, -0.002);
  bg.applyMatrix4(new THREE.Matrix4().makeBasis(V(0, 1, 0), V(0, 0, 1), V(1, 0, 0)));
  bg.rotateY(0.55);
  for (let i = 0; i < blades; i++) { const m = new THREE.Mesh(bg, M.blade); m.rotation.x = (i / blades) * Math.PI * 2; m.castShadow = true; spin.add(m); }
  spin.add(cyl(0.045, 0.05, 0.06, M.charcoal, { axis: 'x', seg: 24 }));
  const cap = sph(0.045, M.charcoal, 0.6, 1, 1, 16); cap.position.x = 0.04; spin.add(cap);
  g.add(cyl(R + 0.012, R + 0.012, 0.12, M.galv, { axis: 'x', seg: 56, open: true }));
  const bell = new THREE.Mesh(new THREE.TorusGeometry(R + 0.012, 0.012, 10, 56), M.galv); bell.rotation.y = Math.PI / 2; bell.position.x = 0.06; g.add(bell);
  const motor = cyl(0.05, 0.05, 0.09, M.dark, { axis: 'x', seg: 20 }); motor.position.x = -0.07; g.add(motor);
  for (let i = 0; i < 3; i++) { const sg = new THREE.Group(); sg.rotation.x = i * 2.094; box(0.008, R, 0.01, M.steel, -0.07, R / 2, 0, sg, false, false); g.add(sg); }
  return { group: g, spin, R };
}

