function makeRV(pos, parent, { flip = false, swap = false } = {}) {
  const g = new THREE.Group(); g.position.copy(pos); parent.add(g);
  const fy = flip ? -1 : 1, fx = swap ? -1 : 1;
  put(cyl(0.03, 0.03, 0.16, M.glass, { axis: 'x', seg: 28, open: true }), g, 0, 0, 0, false, false);
  [-0.08, 0.08].forEach(x => { const c = sph(0.03, M.glass, 0.5, 1, 1, 16); c.position.x = x; g.add(c); put(cyl(0.033, 0.033, 0.008, M.steel, { axis: 'x' }), g, x * 0.98, 0, 0, false); });
  const slider = new THREE.Group(); g.add(slider);
  [-0.028, 0.028].forEach(x => put(cyl(0.026, 0.026, 0.006, M.brass, { axis: 'x' }), slider, x, 0, 0, false));
  put(cyl(0.005, 0.005, 0.056, M.steel, { axis: 'x' }), slider, 0, 0, 0, false);
  const L = { D: V(0, -0.08 * fy, 0), E: V(-0.055 * fx, 0.08 * fy, 0), S: V(0, 0.08 * fy, 0), C: V(0.055 * fx, 0.08 * fy, 0) };
  Object.values(L).forEach(p => put(cyl(0.009, 0.009, 0.05, M.copper), g, p.x, p.y - Math.sign(p.y) * 0.025, 0, false));
  put(cyl(0.024, 0.024, 0.06, M.dark, { axis: 'x' }), g, 0.115, 0, 0);
  put(sph(0.007, M.ledBlue, 1, 1, 1, 8), g, 0.115, 0.027, 0, false, false);
  const W = l => pos.clone().add(l);
  const up = 0.03 * fy, dn = -0.03 * fy;
  const el = {
    rvDE: [L.D, V(0, dn, 0), V(-0.03 * fx, 0, 0), V(L.E.x, up, 0), L.E].map(W),
    rvCS: [L.C, V(L.C.x, up, 0), V(0.03 * fx, 0, 0), V(0, up, 0), L.S].map(W),
    rvDC: [L.D, V(0, dn, 0), V(0.03 * fx, 0, 0), V(L.C.x, up, 0), L.C].map(W),
    rvES: [L.E, V(L.E.x, up, 0), V(-0.03 * fx, 0, 0), V(0, up, 0), L.S].map(W),
  };
  const dense = {};
  Object.entries(el).forEach(([k, v]) => { dense[k] = samplePath(roundedPath(v, 0.012), 0.008); });
  return {
    group: g, slider, dense, ports: { D: W(L.D), E: W(L.E), S: W(L.S), C: W(L.C) }, fx, cur: 0.028 * fx,
    target(mode) { return (mode === 'cool' ? 0.028 : -0.028) * fx; },
  };
}

