// ---------- seasonal set dressing (summer in Cooling, winter in Heating)
const skyPlane = stage.children.find(o => o.material === M.sky);
const skyWinPlane = new THREE.Mesh(skyPlane.geometry, M.skyWin); skyWinPlane.position.copy(skyPlane.position); skyWinPlane.position.z += 0.004; stage.add(skyWinPlane);
Object.assign(M.skyWin, { transparent: true, opacity: 0, depthWrite: false });
const winSkyMat = new THREE.MeshBasicMaterial({ map: skyWinter, transparent: true, opacity: 0, depthWrite: false });
const winSkyBase = stage.children.find(o => o.material === windowSky);
const winSkyPlane = new THREE.Mesh(winSkyBase.geometry, winSkyMat); winSkyPlane.position.copy(winSkyBase.position); winSkyPlane.position.z += 0.004; stage.add(winSkyPlane);
const K = { sunS: C(0xfff0dc), sunW: C(0xdfe9ff), stripC: C(0x5cb6ff), stripH: C(0xff8b3e), white: C(0xffffff), grassW: C(0xa9b7ae), tuftW: C(0xcfdad6), leafS: C(0x3f7d3a), leafW: C(0x2e5c3f), snow: C(0xe6eef5) };
function applyWinter(w) {
  M.skyWin.opacity = w; winSkyMat.opacity = w;
  M.grass.color.lerpColors(K.white, K.grassW, w); M.grass.emissive.copy(K.snow); M.grass.emissiveIntensity = w * 0.5;
  M.tuft.color.lerpColors(K.white, K.tuftW, w); M.tuft.emissive.copy(K.snow); M.tuft.emissiveIntensity = w * 0.4;
  M.leaf.color.lerpColors(K.leafS, K.leafW, w); M.leaf.emissive.copy(K.snow); M.leaf.emissiveIntensity = w * 0.1;
  sun.color.lerpColors(K.sunS, K.sunW, w); sun.intensity = lerp(2.7, 2.15, w);
  M.strip.color.lerpColors(K.stripC, K.stripH, w);
}

// ---------- state
const state = { system: 'split', mode: 'cool', playing: !reduceMotion.matches };
const SYS_NAME = { split: 'Split system', mono: 'Monoblock' }, MODE_NAME = { cool: 'Cooling', heat: 'Heating' };
const SCEN = { cool: { inA: 27.4, inB: 23.0, out: 35.0, sup: 12.5, exh: 44.0 }, heat: { inA: 16.2, inB: 21.5, out: 3.0, sup: 41.0, exh: -3.5 } };
const sim = { time: 0, speed: state.playing ? 1 : 0, fade: 1, fadeTarget: 1, pending: false, refresh: 3, sys: null, mode: null, winter: 0, snow: 0, tIn: SCEN.cool.inA, ready: false, homeLock: true };
const fmt = v => `${v < 0 ? '\u2212' : ''}${Math.abs(v).toFixed(1)} \u00b0C`;
const setText = (n, s) => { if (n.textContent !== s) n.textContent = s; };
const ui = { state: $('#stState'), tIn: $('#tIn'), tOut: $('#tOut'), tSup: $('#tSup'), tExh: $('#tExh'), abs: $('#stAbs'), rel: $('#stRel') };
const activeSys = () => systems[sim.sys || state.system];

// ---------- camera + controls
const controls = new OrbitControls(camera, canvas);
Object.assign(controls, { enableDamping: true, dampingFactor: 0.08, rotateSpeed: 0.65, zoomSpeed: 0.8, panSpeed: 0.7, screenSpacePanning: true, minDistance: 0.45, maxDistance: 24, minPolarAngle: 0.35, maxPolarAngle: 1.62, minAzimuthAngle: -1.15, maxAzimuthAngle: 1.15 });
controls.mouseButtons = { LEFT: THREE.MOUSE.ROTATE, MIDDLE: THREE.MOUSE.DOLLY, RIGHT: THREE.MOUSE.PAN };
controls.touches = { ONE: THREE.TOUCH.ROTATE, TWO: THREE.TOUCH.DOLLY_PAN };
const homeView = () => {
  const a = camera.aspect, target = V(0.3, 1.25, -0.6), dist = a >= 1.5 ? 9.2 : clamp(8.6 / (0.5735 * a), 9.2, 22);
  return [target.clone().add(V(0.02, 0.1, 1).normalize().multiplyScalar(dist)), target];
};
const fly = { on: false, t: 0, dur: 1, p0: V(), t0: V(), p1: V(), t1: V() };
function flyTo(pos, target, dur = 1.5) {
  if (reduceMotion.matches || dur <= 0) { fly.on = false; camera.position.copy(pos); controls.target.copy(target); controls.update(); return; }
  Object.assign(fly, { on: true, t: 0, dur }); fly.p0.copy(camera.position); fly.t0.copy(controls.target); fly.p1.copy(pos); fly.t1.copy(target);
}
function flyHome(dur = 1.4) { const [p, t] = homeView(); sim.homeLock = true; flyTo(p, t, dur); }
controls.addEventListener('start', () => { fly.on = false; sim.homeLock = false; });
function zoomBy(f) {
  const off = camera.position.clone().sub(controls.target), len = off.length(), nl = clamp(len * f, controls.minDistance, controls.maxDistance);
  sim.homeLock = false; flyTo(controls.target.clone().add(off.multiplyScalar(nl / len)), controls.target.clone(), 0.35);
}
const TB = { min: V(-3.5, -0.2, -2.5), max: V(4.0, 3.0, 1.0) }, tclamp = V();
function clampTarget() {
  tclamp.copy(controls.target).clamp(TB.min, TB.max);
  if (!tclamp.equals(controls.target)) { const d = tclamp.sub(controls.target); controls.target.add(d); camera.position.add(d); }
}

// ---------- post-processing (falls back to direct rendering)
let composer = null;
try {
  const rt = new THREE.WebGLRenderTarget(4, 4, { type: THREE.HalfFloatType, samples: small() ? 0 : 4 });
  composer = new EffectComposer(renderer, rt);
  composer.addPass(new RenderPass(scene, camera));
  composer.addPass(new UnrealBloomPass(new THREE.Vector2(256, 256), 0.42, 0.55, 0.92));
  composer.addPass(new OutputPass());
} catch (err) { console.warn('Post-processing disabled', err); composer = null; }

function resize() {
  const w = innerWidth, h = innerHeight, pr = Math.min(devicePixelRatio || 1, small() ? 1.75 : 2);
  renderer.setPixelRatio(pr); renderer.setSize(w, h, false);
  if (composer) { composer.setPixelRatio(pr); composer.setSize(w, h); }
  camera.aspect = w / h; camera.updateProjectionMatrix();
  const px = renderer.domElement.height / (2 * Math.tan(THREE.MathUtils.degToRad(camera.fov / 2)));
  pointMats.forEach(m => { m.uniforms.uScale.value = px; });
  if (sim.homeLock && !fly.on) { const [p, t] = homeView(); camera.position.copy(p); controls.target.copy(t); controls.update(); }
}
addEventListener('resize', resize);
const watchDpr = () => matchMedia(`(resolution: ${devicePixelRatio}dppx)`).addEventListener('change', () => { resize(); watchDpr(); }, { once: true });
watchDpr();
canvas.addEventListener('webglcontextlost', e => { e.preventDefault(); sim.lost = true; showFallback('The graphics context was lost. Reload to restore the 3D view.'); });

// ---------- labels
const labelsRoot = $('#labels'), leaders = $('#leaders'), NS = 'http://www.w3.org/2000/svg';
function makeLabel(def, chip = false) {
  const el = document.createElement('div'); el.className = 'lbl' + (chip ? ' chip' : '');
  el.innerHTML = chip ? '<div class="pill"><em></em><b></b></div>' : '<i class="dot"></i><div class="pill"><b></b><em></em></div>';
  labelsRoot.appendChild(el);
  let line = null;
  if (!chip) { line = document.createElementNS(NS, 'line'); line.style.display = 'none'; leaders.appendChild(line); }
  return { def, el, pill: $('.pill', el), b: $('b', el), em: $('em', el), line, w: 0, h: 0, shown: false };
}
function roleText(d, mode) {
  if (d.role === 'ic') return mode === 'cool' ? ['Indoor coil', 'Evaporator \u00b7 absorbs room heat', 'absorb'] : ['Indoor coil', 'Condenser \u00b7 releases heat', 'release'];
  if (d.role === 'oc') return mode === 'cool' ? ['Outdoor coil', 'Condenser \u00b7 releases heat', 'release'] : ['Outdoor coil', 'Evaporator \u00b7 absorbs heat', 'absorb'];
  return [d.name, d.sub, ''];
}
function refreshLabelTexts(S, mode) {
  S.lb.forEach(L => {
    const [n, s, cls] = roleText(L.def, mode);
    L.b.textContent = n; L.em.textContent = s || ''; L.em.hidden = !s;
    L.el.classList.toggle('absorb', cls === 'absorb'); L.el.classList.toggle('release', cls === 'release');
    L.w = L.pill.offsetWidth; L.h = L.pill.offsetHeight;
  });
}
Object.values(systems).forEach(S => { S.lb = S.labels.map(d => makeLabel(d)); });
const chips = [makeLabel({ key: 'chipIn', pos: V(-1.9, 2.3, -0.3), chip: 'Indoor' }, true), makeLabel({ key: 'chipOut', pos: V(2.3, 2.05, -0.3), chip: 'Outdoor' }, true)];
chips.forEach(c => { c.em.textContent = c.def.chip; });
let focusKey = null;
const pv = V();
function updateLabels() {
  const S = systems[sim.sys]; if (!S) return;
  const W = innerWidth, H = innerHeight, dist = camera.position.distanceTo(controls.target), ok = sim.fade > 0.6;
  let cand = S.lb.filter(L => {
    const d = L.def; L.shown = false;
    if (!ok || (d.mode && d.mode !== sim.mode)) return false;
    if (d.pos.distanceTo(controls.target) > Math.max(0.5, dist * 0.6)) return false;
    return d.key === focusKey || d.pri === 1 || dist < 4.8;
  });
  cand.sort((a, b) => (b.def.key === focusKey) - (a.def.key === focusKey) || a.def.pri - b.def.pri || a.def.pos.distanceTo(controls.target) - b.def.pos.distanceTo(controls.target));
  if (cand.length > (small() ? 4 : 10)) cand = cand.slice(0, small() ? 4 : 10);
  if (ok && dist > 5.5) cand.push(...chips); else chips.forEach(c => { c.shown = false; });
  const items = [];
  for (const L of cand) {
    pv.copy(L.def.pos).project(camera);
    if (pv.z >= 1 || Math.abs(pv.x) > 1.02 || Math.abs(pv.y) > 1.02) continue;
    const ax = (pv.x * 0.5 + 0.5) * W, ay = (-pv.y * 0.5 + 0.5) * H, off = L.def.off || [0, 0];
    if (!L.w) { L.w = L.pill.offsetWidth; L.h = L.pill.offsetHeight; }
    items.push({ L, ax, ay, px: ax + off[0], py: ay + off[1], w: L.w, h: L.h });
  }
  items.sort((a, b) => a.py - b.py);
  for (let pass = 0; pass < 3; pass++) for (let i = 1; i < items.length; i++) for (let j = 0; j < i; j++) {
    const a = items[i], b = items[j];
    if (Math.abs(a.px - b.px) < (a.w + b.w) / 2 + 6 && Math.abs(a.py - b.py) < (a.h + b.h) / 2 + 4) a.py = b.py + (a.h + b.h) / 2 + 4;
  }
  for (const it of items) {
    const { L } = it;
    it.px = clamp(it.px, it.w / 2 + 8, W - it.w / 2 - 8); it.py = clamp(it.py, it.h / 2 + 8, H - it.h / 2 - 8);
    L.shown = true; L.el.classList.add('show');
    if (L.line) {
      L.el.style.transform = `translate3d(${it.ax.toFixed(1)}px,${it.ay.toFixed(1)}px,0)`;
      L.pill.style.transform = `translate(${(it.px - it.ax).toFixed(1)}px,${(it.py - it.ay).toFixed(1)}px) translate(-50%,-50%)`;
      const ex = clamp(it.ax, it.px - it.w / 2, it.px + it.w / 2), ey = clamp(it.ay, it.py - it.h / 2, it.py + it.h / 2), inside = ex === it.ax && ey === it.ay;
      L.line.style.display = inside ? 'none' : '';
      L.line.setAttribute('x1', it.ax.toFixed(1)); L.line.setAttribute('y1', it.ay.toFixed(1)); L.line.setAttribute('x2', ex.toFixed(1)); L.line.setAttribute('y2', ey.toFixed(1));
    } else {
      L.el.style.transform = `translate3d(${it.px.toFixed(1)}px,${it.py.toFixed(1)}px,0)`;
    }
  }
  [...S.lb, ...chips].forEach(L => { if (!L.shown) { L.el.classList.remove('show'); if (L.line) L.line.style.display = 'none'; } });
}

// ---------- commit a system/mode change to the scene
function commitScene() {
  const S = systems[state.system], mode = state.mode, modeChanged = sim.mode !== mode;
  Object.values(systems).forEach(s => {
    s.group.visible = s === S;
    if (s !== S) s.lb.forEach(L => { L.shown = false; L.el.classList.remove('show'); if (L.line) L.line.style.display = 'none'; });
  });
  sim.sys = state.system; sim.mode = mode;
  S.flow.cool.group.visible = mode === 'cool'; S.flow.heat.group.visible = mode === 'heat';
  S.water.forEach(w => { w.mesh.visible = w.mode === mode; });
  S.streams.forEach(st => st.applyTemp(st.kind === 'room' ? (mode === 'cool' ? -1 : 1) : (mode === 'cool' ? 1 : -1)));
  const evap = mode === 'cool' ? S.coils.ic : S.coils.oc, cond = mode === 'cool' ? S.coils.oc : S.coils.ic;
  evap.setTint(CL.gas, CL.mix); cond.setTint(CL.hot, CL.warm);
  S.dew = S.dew || { ic: 0, oc: 0 };
  refreshLabelTexts(S, mode);
  if (modeChanged) { sim.tIn = SCEN[mode].inA; }
  sim.pending = false; sim.refresh = 3;
  const ic = mode === 'cool';
  setText(ui.abs, ic ? 'Indoor coil' : 'Outdoor coil'); setText(ui.rel, ic ? 'Outdoor coil' : 'Indoor coil');
}
function syncButtons() {
  document.body.dataset.system = state.system; document.body.dataset.mode = state.mode;
  $$('button[data-system]').forEach(b => b.setAttribute('aria-pressed', String(b.dataset.system === state.system)));
  $$('button[data-mode]').forEach(b => b.setAttribute('aria-pressed', String(b.dataset.mode === state.mode)));
  setText(ui.state, `${SYS_NAME[state.system]} \u00b7 ${MODE_NAME[state.mode]}`);
}
function requestState(next) {
  const system = next.system || state.system, mode = next.mode || state.mode;
  if (system === state.system && mode === state.mode) return false;
  const sysChanged = system !== state.system;
  state.system = system; state.mode = mode; syncButtons();
  sim.pending = true;
  if (reduceMotion.matches || !sim.ready) commitScene(); else sim.fadeTarget = 0;
  if (sysChanged) { if (tour.on) goStep(tour.i); else flyHome(); }
  return true;
}
$$('button[data-system]').forEach(b => b.addEventListener('click', () => requestState({ system: b.dataset.system })));
$$('button[data-mode]').forEach(b => b.addEventListener('click', () => requestState({ mode: b.dataset.mode })));

// ---------- play / pause / reset / zoom
function syncPlay() {
  const b = $('#btnPlay');
  b.setAttribute('aria-pressed', String(state.playing));
  $('#txtPlay').textContent = state.playing ? 'Pause' : 'Play';
  $('#icoPlay').innerHTML = state.playing ? '<path d="M7 5v14M17 5v14"/>' : '<path d="M8 5v14l11-7z"/>';
}
$('#btnPlay').addEventListener('click', () => { state.playing = !state.playing; syncPlay(); });
$('#btnReset').addEventListener('click', () => { if (tour.on) stopTour(false); flyHome(1.1); });
$('#btnZoomIn').addEventListener('click', () => zoomBy(0.72));
$('#btnZoomOut').addEventListener('click', () => zoomBy(1.38));
canvas.addEventListener('keydown', e => { if (e.code === 'Space') { e.preventDefault(); $('#btnPlay').click(); } });
reduceMotion.addEventListener?.('change', () => { if (reduceMotion.matches && state.playing) { state.playing = false; syncPlay(); } });

// ---------- guided explanation
const TOUR = [
  { cam: 'wide', mode: 'cool', focus: null, t: 'Air conditioning does not make cold. It moves heat out of the room, using refrigerant that runs in a sealed loop.' },
  { cam: 'ic', mode: 'cool', focus: 'ic', t: 'Cold refrigerant in the indoor coil absorbs heat from room air and boils into gas. The cooled air returns to the room; moisture condenses and drips away.' },
  { cam: 'comp', mode: 'cool', focus: 'comp', t: 'The compressor squeezes the gas, raising its pressure and temperature above the outdoor air.' },
  { cam: 'oc', mode: 'cool', focus: 'oc', t: 'In the outdoor coil the hot gas gives its heat to outdoor air and condenses back into liquid.' },
  { cam: 'eev', mode: 'cool', focus: 'eev', t: 'The expansion valve drops the pressure, so the liquid turns very cold, ready to absorb heat again.' },
  { cam: 'wall', mode: 'cool', focus: 'wall', t: { split: 'Only sealed refrigerant lines cross the wall. Room air and outdoor air never mix.', mono: 'The whole loop sits in one cabinet. Two ducts carry outdoor air in and out; that air never enters the room.' } },
  { cam: 'rv', mode: 'heat', focus: 'rv', t: 'Heating: the reversing valve flips the flow. The indoor coil now releases heat and the outdoor coil absorbs it.' },
  { cam: 'wide', mode: 'heat', focus: null, t: 'Even cold outdoor air holds heat. The system pumps it inside, so it moves heat in instead of making it.' },
];
const STEP_SECONDS = 8;
const tour = { on: false, i: 0, t: 0, done: false };
const cap = { root: $('#caption'), step: $('#capStep'), dots: $('#capDots'), text: $('#capText'), bar: $('#capBar') };
TOUR.forEach((_, i) => { const b = document.createElement('button'); b.type = 'button'; b.setAttribute('aria-label', `Step ${i + 1}`); b.addEventListener('click', () => goStep(i)); cap.dots.appendChild(b); });
const focusRing = new THREE.Mesh(new THREE.RingGeometry(0.9, 1, 64), new THREE.MeshBasicMaterial({ color: K.stripC, transparent: true, opacity: 0.85, depthTest: false, depthWrite: false, side: THREE.DoubleSide, toneMapped: false }));
focusRing.renderOrder = 30; focusRing.visible = false; scene.add(focusRing);
function syncGuide() {
  $('#txtGuide').textContent = tour.on ? 'Stop' : tour.done ? 'Replay' : 'Guide';
  $('#icoGuide').innerHTML = tour.on ? '<rect x="7" y="7" width="10" height="10" rx="1.5"/>' : tour.done ? '<path d="M3 12a9 9 0 1 0 3-6.7"/><path d="M3 4v5h5"/>' : '<circle cx="12" cy="12" r="9"/><path d="M10 8.5l5 3.5-5 3.5z"/>';
  $('#btnGuide').setAttribute('aria-pressed', String(tour.on));
}
function goStep(i) {
  tour.i = clamp(i, 0, TOUR.length - 1); tour.t = 0;
  const s = TOUR[tour.i];
  if (s.mode) requestState({ mode: s.mode });
  const S = systems[state.system];
  if (s.cam === 'wide') flyHome(1.6); else { const c = S.cams[s.cam]; sim.homeLock = false; flyTo(c[0], c[1], 1.6); }
  focusKey = s.focus;
  setText(cap.text, typeof s.t === 'string' ? s.t : s.t[state.system]);
  setText(cap.step, `${tour.i + 1} / ${TOUR.length}`);
  [...cap.dots.children].forEach((d, k) => { d.classList.toggle('on', k === tour.i); d.classList.toggle('past', k < tour.i); });
  cap.bar.style.width = '0%';
  [...S.lb].forEach(L => L.el.classList.toggle('focus', L.def.key === focusKey));
  focusRing.visible = !!s.focus;
}
function startTour() {
